classes.source:
@startuml
class Probe {
  level: Integer
  crystals: Integer
  scanAll(rocks: Sequence<Asteroid>)
  scanPower(): Integer
}
class Asteroid {
  unscanned: Integer
  crystals: Integer
  tagged: Integer
  scan(power: Integer): Integer
  collectSample(): Integer
  tag(passes: Integer)
}
class SoundPlayer {
  play(sound: String)
}
class StarMap {
  rocks: Integer
}
Probe --> "1" SoundPlayer : sfx
Probe --> "0..1" StarMap : starMap
Probe ..> Asteroid
@enduml
